Lemma art_cr_sec : forall cost, 1 <= fst cr -> 0 <= cost <= snd cr ->
  Z.of_nat (length (g_sec FSG G)) + 1 <= 16384 /\ Z.of_nat (length (art_live (g_log FSG G))) < KMAX
